/bin/bash -lc "node --input-type=module <<'EOF'
const cases = [
  { member: 'Alice', team: 'Engineering', region: 'eu-west' },
  { member: 'Bob', team: 'Design', region: 'ap-south' },
]
for (const { member, team, region } of cases) {
  const response = await fetch('http://localhost:3100/', {
    headers: { cookie: "'`member=${member}; team=${team}`, '"'x-region': region, 'accept-encoding': 'identity' },
  })
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  const first = await reader.read()
  let html = decoder.decode(first.value ?? new Uint8Array())
  for (;;) {
    const chunk = await reader.read()
    if (chunk.done) break
    html += decoder.decode(chunk.value)
  }
  console.log(JSON.stringify({
    status: response.status,
    member,
    firstChunkHasFrame: first.value && html.includes('<h1>Workspace</h1>') && decoder.decode(first.value).includes('12 active projects'),
    firstChunkHasFallback: decoder.decode(first.value).includes('Loading your workspace details'),
    hasOwnDetails: html.includes("'`Welcome, ${member}`) && html.includes(`Team: ${team}`) && html.includes(`Region: ${region}`),
    hasOtherMember: html.includes(member === '"'Alice' ? 'Welcome, Bob' : 'Welcome, Alice'),
  }))
}
EOF"

